import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.mockito.Mockito;

@RunWith(JUnit4.class)
public class UrlBuilderTest {

    @Test
    public void constructorWithInputUrl() {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(inputUrl, urlBuilder.url_);
    }

    @Test
    public void buildUrl() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URI uri = UriUtil.buildUri(urlBuilder.url_);
        assertEquals(new URL("http://example.com"), new URL(uri.toString()));
    }

    @Test
    public void buildUrlWithQuery() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("http://example.com?query=string");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URI uri = UriUtil.buildUri(urlBuilder.url_);
        assertEquals(new URL("http://example.com?query=string"), new URL(uri.toString()));
    }

    @Test
    public void appendKeyVal() throws UnsupportedEncodingException {
        Connection.KeyVal kv = Mockito.mock(Connection.KeyVal.class);
        UrlBuilder urlBuilder = new UrlBuilder(null);
        urlBuilder.appendKeyVal(kv);
        verify(kv).setString(Mockito.anyString());
    }

    @Test
    public void appendKeyValWithEncodedValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = Mockito.mock(Connection.KeyVal.class);
        String encodedValue = URLEncoder.encode("string", DataUtil.UTF_8.name());
        when(kv.getString()).thenReturn(encodedValue);
        UrlBuilder urlBuilder = new UrlBuilder(null);
        urlBuilder.appendKeyVal(kv);
        verify(kv).setString(encodedValue);
    }

    @Test
    public void appendKeyValWithNonEncodedValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = Mockito.mock(Connection.KeyVal.class);
        String nonEncodedValue = "string";
        when(kv.getString()).thenReturn(nonEncodedValue);
        UrlBuilder urlBuilder = new UrlBuilder(null);
        urlBuilder.appendKeyVal(kv);
        verify(kv).setString(nonEncodedValue);
    }

}

